      "官方强调，任何非认证渠道的陌生链接或二维码均不属于小鹏汽车官方服务范围，且不会收取任何费用。国家市场监督管理总局也在其公众号提醒车主，应直接访问官方网站查询官方召回信息，切勿轻信陌生来电或点击不明链接。小鹏汽车建议车主如遇可疑情况，应立即报警。此次事件凸显了企业与政府在防范电信网络诈骗方面的合作，通过官方渠道确保用户权益不受侵害。",
