    img: '/static/picture/1752658217587676.jpg',
    summary: "微信调整短剧审核规则，要求单集时长提升至1分钟，并明确AI生成内容需提交制作证明。此举旨在提升短剧质量，规范AI内容的使用。",
    content: [
      "近日，微信宣布对短剧审核规则进行调整，将单集最低时长从45秒提高至1分钟，同时新增了AI生成内容的制作证明要求。这些调整将于2023年12月1日生效，旨在优化短剧内容体验，提升叙事完整性。",
      "针对使用AI生成内容的剧集，创作者需提交展示AI软件制作过程的视频，内容需包括资产列表、剧集列表以及分镜提示词等，部分还需播放少量分镜片段以证明作品的真实来源。此前，该视频为选填项，但从12月1日起将变成必填项，此举有助于规范AI内容的使用，防止盗版等问题。",
      "为确保新规则顺利实施，微信建议创作者提前准备好相关视频，避免因材料不完整或工程文件问题导致退回修改。此调整体现了平台对提升短剧质量、引导创作者规范化创作的重视。",
      "此次调整不仅限于内容审核，还涉及SEO优化和AI技术的应用，体现了微信在数字化内容管理上的持续努力。"
]
