    id: '105',
    title: "员工请愿反对：中小学使用含AI功能的谷歌搜索",
    category: '公司新闻',
    date: '2026-11-20',
    day: '20',
    yearMonth: '2026-11',
    img: '/static/picture/1752658217587676.jpg',
    summary: "超过500名谷歌员工联名请愿，反对扩大AI功能在校园的使用，担心这会削弱学生的批判性思维能力。谷歌回应称将与学校合作，确保产品能够帮助学生和教师。",
    content: [
      "近日，超过500名谷歌员工及其合作者联名向公司高层请愿，反对扩大AI功能在校园的使用。请愿书明确指出，如果学校不愿使用AI，就不应使用谷歌搜索。此举源于谷歌决定扩大AI服务的覆盖范围，让许多中小学生能够体验到Gemini的功能，引发了教育工作者、家长和政策制定者的广泛质疑和担忧。",
      "请愿书强调，AI的介入可能会削弱学生的批判性思维能力，使他们依赖于AI生成的答案，不再主动探索其他信息来源。尽管谷歌表示将与学校密切合作，确保产品能够帮助学生和教师，但员工们认为，如果不向学生提供AI功能，其他公司可能会采取更加不负责任的做法。",
      "值得注意的是，谷歌管理层曾表示，扩大AI服务可以确保谷歌在竞争中保持优势。然而，部分员工对此表示质疑，认为技术上推出不带AI功能的谷歌搜索版本是可行的，但此举可能会削弱谷歌在教育市场的竞争力。这一请愿事件不仅反映了谷歌在AI伦理和教育领域的挑战，也凸显了员工对企业决策的不同看法。",
      "此次请愿事件再次凸显了AI技术在教育领域的复杂性，企业需要平衡技术创新与教育伦理之间的关系，满足广大用户的需求。"
]
